def maxPartitionFactor(points):
    n = len(points)
    # No intra-group pairs when n == 2
    if n == 2:
        return 0

    # Precompute all pairwise Manhattan distances
    dist = [[abs(a[0] - b[0]) + abs(a[1] - b[1]) for b in points] for a in points]

    def feasible(d):
        # Points closer than d must be in different groups: check graph is bipartite
        color = [-1] * n
        for s in range(n):
            if color[s] != -1:
                continue
            color[s] = 0
            stack = [s]
            while stack:
                u = stack.pop()
                for v in range(n):
                    if v != u and dist[u][v] < d:
                        if color[v] == -1:
                            color[v] = color[u] ^ 1
                            stack.append(v)
                        elif color[v] == color[u]:
                            return False
        return True

    # Binary search the largest feasible d (d = 0 is always feasible)
    lo, hi = 0, max(max(row) for row in dist)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
